-- 윤식단: 세트 구성 페이지에서 내려간 세트
update public.health_meal_products set is_available=false, updated_at=now() where source='yundiet' and name in ('밥도감 12팩 전메뉴','밥도감 18팩 전메뉴 + 인기 6가지','밥도감 9팩 맛보기');
update public.product_prices pp set is_available=false from public.products p where p.id=pp.product_id and pp.platform='yundiet' and p.name in ('밥도감 12팩 전메뉴','밥도감 18팩 전메뉴 + 인기 6가지','밥도감 9팩 맛보기');
-- 확인한 나머지는 확인 시각만 새로
update public.health_meal_products set last_crawled_at=now() where source in ('sixmeal','makesalad','greating','yundiet') and is_available;
update public.product_prices set last_crawled_at=now() where platform in ('sixmeal','makesalad','greating','yundiet') and is_available;
commit;
